-- Expand only: a new table.
CREATE TABLE "proceeding_state_change" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"proceeding_id" uuid NOT NULL,
	"from_state" "proceeding_state" NOT NULL,
	"to_state" "proceeding_state" NOT NULL,
	"reason" text,
	"actor_member_id" uuid,
	"cure_deadline" date,
	"changed_at" timestamp with time zone DEFAULT now() NOT NULL,
	"source_type" "source_type" NOT NULL,
	"source_ref" text,
	"anchor_id" uuid,
	"confidence" numeric(4, 3),
	"confirmation_state" "confirmation_state" DEFAULT 'proposed' NOT NULL,
	"captured_at" timestamp with time zone DEFAULT now() NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"workspace_id" uuid NOT NULL,
	CONSTRAINT "proceeding_state_change_workspace_id_id_uq" UNIQUE("workspace_id","id"),
	CONSTRAINT "proceeding_state_change_provenance_chk" CHECK ((source_type = 'manual' or anchor_id is not null or source_ref is not null) and (confidence is null or (confidence >= 0 and confidence <= 1))),
	CONSTRAINT "proceeding_state_change_not_same_chk" CHECK (from_state <> to_state),
	CONSTRAINT "proceeding_state_change_reason_chk" CHECK (reason is null or btrim(reason) <> ''),
	CONSTRAINT "proceeding_state_change_cure_deadline_chk" CHECK (cure_deadline is null or to_state = 'defects'),
	CONSTRAINT "proceeding_state_change_reopen_reason_chk" CHECK (from_state <> 'disposed' or to_state <> 'numbered' or reason is not null)
);
